import{_ as i,W as t,s as d,u as o,ah as c,I as l,w as a,Z as p,A as e}from"./chunks/framework.Dx7wo2et.js";import"./chunks/theme.CjgFg8Ql.js";const x=JSON.parse('{"title":"在 Linux 中锁定和解锁用户帐户的三种方法 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中锁定和解锁用户帐户的三种方法 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中锁定和解锁用户帐户的三种方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中锁定和解锁用户帐户的三种方法 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190621 Three Ways to Lock and Unlock User Account in Linux","title":"在 Linux 中锁定和解锁用户帐户的三种方法","tag":"201907"},"relativePath":"201907/20190621 Three Ways to Lock and Unlock User Account in Linux.md","filePath":"[post].md"}'),u={name:"201907/20190621 Three Ways to Lock and Unlock User Account in Linux.md"};function r(h,s,g,k,b,v){const n=t("Link");return o(),d("div",null,[s[15]||(s[15]=c(`<h1 id="在-linux-中锁定和解锁用户帐户的三种方法" tabindex="-1">在 Linux 中锁定和解锁用户帐户的三种方法 <a class="header-anchor" href="#在-linux-中锁定和解锁用户帐户的三种方法" aria-label="Permalink to 在 Linux 中锁定和解锁用户帐户的三种方法">​</a></h1><p><img src="https://linux.cn/article-11043-1.html" alt=""></p><p>如果你已经在你的组织中实施了某种密码策略，你无需看这篇文章了。但是在这种情况下，如果你给账户设置了 24 小时的锁定期，你需要手动解锁用户帐户。</p><p>本教程将帮助你在 Linux 中手动锁定和解锁用户帐户。</p><p>这可以通过三种方式使用以下两个 Linux 命令来完成。</p><ul><li><code>passwd</code>：用于更新用户的身份验证令牌。这个任务是通过调用 Linux PAM 和 libuser API 来实现。</li><li><code>usermod</code>：用于修改/更新给定用户的帐户信息。它用于将用户添加到特定的组中等等功能。</li></ul><p>为了说明这一点，我们选择 <code>daygeek</code> 用户帐户。让我们看看，怎么一步步来实现的。</p><p>请注意，你必须使用你需要锁定或解锁的用户的帐户，而不是我们的帐户。你可以使用 <code>id</code> 命令检查给定的用户帐户在系统中是否可用。是的，我的这个帐户在我的系统中是可用的。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># id daygeek</span></span>
<span class="line"><span></span></span>
<span class="line"><span>uid=2240(daygeek) gid=2243(daygeek) groups=2243(daygeek),2244(ladmin)</span></span></code></pre></div><h3 id="方法1-如何使用-passwd-命令锁定、解锁和检查-linux-中给定用户帐户的状态" tabindex="-1">方法1: 如何使用 passwd 命令锁定、解锁和检查 Linux 中给定用户帐户的状态？ <a class="header-anchor" href="#方法1-如何使用-passwd-命令锁定、解锁和检查-linux-中给定用户帐户的状态" aria-label="Permalink to 方法1: 如何使用 passwd 命令锁定、解锁和检查 Linux 中给定用户帐户的状态？">​</a></h3><p><code>passwd</code> 命令是 Linux 管理员经常使用的命令之一。它用于更新 <code>/etc/shadow</code> 文件中用户的身份验证令牌。</p><p>使用 <code>-l</code> 开关运行 <code>passwd</code> 命令，锁定给定的用户帐户。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># passwd -l daygeek</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Locking password for user daygeek.</span></span>
<span class="line"><span>passwd: Success</span></span></code></pre></div><p>你可以通过 <code>passwd</code> 命令或从 <code>/etc/shadow</code> 文件中获取给定用户名来检查锁定的帐户状态。</p><p>使用 <code>passwd</code> 命令检查用户帐户锁定状态。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># passwd -S daygeek</span></span>
<span class="line"><span>或</span></span>
<span class="line"><span># passwd --status daygeek</span></span>
<span class="line"><span></span></span>
<span class="line"><span>daygeek LK 2019-05-30 7 90 7 -1 (Password locked.)</span></span></code></pre></div><p>这将输出给定帐户密码状态的简短信息。</p><ul><li><code>LK</code>：密码被锁定</li><li><code>NP</code>：没有设置密码</li><li><code>PS</code>：密码已设置</li></ul><p>使用 <code>/etc/shadow</code> 文件检查锁定的用户帐户状态。如果帐户已被锁定，密码前面将添加两个感叹号。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># grep daygeek /etc/shadow</span></span>
<span class="line"><span></span></span>
<span class="line"><span>daygeek:!!$6$tGvVUhEY$PIkpI43HPaEoRrNJSRpM3H0YWOsqTqXCxtER6rak5PMaAoyQohrXNB0YoFCmAuh406n8XOvBBldvMy9trmIV00:18047:7:90:7:::</span></span></code></pre></div><p>使用 <code>-u</code> 开关运行 <code>passwd</code> 命令，可以解锁给定的用户帐户。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># passwd -u daygeek</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Unlocking password for user daygeek.</span></span>
<span class="line"><span>passwd: Success</span></span></code></pre></div><h3 id="方法2-如何使用-usermod-命令在-linux-中锁定、解锁和检查给定用户帐户的状态" tabindex="-1">方法2：如何使用 usermod 命令在 Linux 中锁定、解锁和检查给定用户帐户的状态？ <a class="header-anchor" href="#方法2-如何使用-usermod-命令在-linux-中锁定、解锁和检查给定用户帐户的状态" aria-label="Permalink to 方法2：如何使用 usermod 命令在 Linux 中锁定、解锁和检查给定用户帐户的状态？">​</a></h3><p><code>usermod</code> 命令也经常被 Linux 管理员使用。<code>usermod</code> 命令用于修改/更新给定用户的帐户信息。它用于将用户添加到特定的组中，等等。</p><p>使用 <code>-L</code> 开关运行 <code>usermod</code> 命令，锁定给定的用户帐户。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># usermod --lock daygeek</span></span>
<span class="line"><span>或</span></span>
<span class="line"><span># usermod -L daygeek</span></span></code></pre></div><p>你可以通过 <code>passwd</code> 命令或从 <code>/etc/shadow</code> 文件中获取给定用户名来检查锁定的帐户状态。</p><p>使用 <code>passwd</code> 命令检查用户帐户锁定状态。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># passwd -S daygeek</span></span>
<span class="line"><span>或</span></span>
<span class="line"><span># passwd --status daygeek</span></span>
<span class="line"><span></span></span>
<span class="line"><span>daygeek LK 2019-05-30 7 90 7 -1 (Password locked.)</span></span></code></pre></div><p>这将输出给定帐户密码状态的简短信息。</p><ul><li><code>LK</code>：密码被锁定</li><li><code>NP</code>：没有设置密码</li><li><code>PS</code>：密码已设置</li></ul><p>使用 <code>/etc/shadow</code> 文件检查锁定的用户帐户状态。如果帐户已被锁定，密码前面将添加两个感叹号。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># grep daygeek /etc/shadow</span></span>
<span class="line"><span></span></span>
<span class="line"><span>daygeek:!!$6$tGvVUhEY$PIkpI43HPaEoRrNJSRpM3H0YWOsqTqXCxtER6rak5PMaAoyQohrXNB0YoFCmAuh406n8XOvBBldvMy9trmIV00:18047:7:90:7:::</span></span></code></pre></div><p>使用 <code>-U</code> 开关运行 <code>usermod</code> 命令以解锁给定的用户帐户。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># usermod --unlock daygeek</span></span>
<span class="line"><span>或</span></span>
<span class="line"><span># usermod -U daygeek</span></span></code></pre></div><h3 id="方法-3-如何在-linux-中使用-usermod-命令禁用、启用对给定用户帐户的-ssh-访问" tabindex="-1">方法-3：如何在 Linux 中使用 usermod 命令禁用、启用对给定用户帐户的 SSH 访问？ <a class="header-anchor" href="#方法-3-如何在-linux-中使用-usermod-命令禁用、启用对给定用户帐户的-ssh-访问" aria-label="Permalink to 方法-3：如何在 Linux 中使用 usermod 命令禁用、启用对给定用户帐户的 SSH 访问？">​</a></h3><p><code>usermod</code> 命令也是经常被 Linux 管理员使用的命令。<code>usermod</code> 命令用于修改/更新给定用户的帐户信息。它用于将用户添加到特定的组中，等等。</p><p>替代的，锁定可以通过将 <code>nologin</code> shell 分配给给定用户来完成。为此，可以运行以下命令。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># usermod -s /sbin/nologin daygeek</span></span></code></pre></div><p>你可以通过从 <code>/etc/passwd</code> 文件中给定用户名来检查锁定的用户帐户详细信息。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># grep daygeek /etc/passwd</span></span>
<span class="line"><span></span></span>
<span class="line"><span>daygeek:x:2240:2243::/home/daygeek:/sbin/nologin</span></span></code></pre></div><p>我们可以通过分配回原来的 shell 来启用用户的 ssh 访问。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># usermod -s /bin/bash daygeek</span></span></code></pre></div><h3 id="如何使用-shell-脚本锁定、解锁和检查-linux-中多个用户帐户的状态" tabindex="-1">如何使用 shell 脚本锁定、解锁和检查 Linux 中多个用户帐户的状态？ <a class="header-anchor" href="#如何使用-shell-脚本锁定、解锁和检查-linux-中多个用户帐户的状态" aria-label="Permalink to 如何使用 shell 脚本锁定、解锁和检查 Linux 中多个用户帐户的状态？">​</a></h3><p>如果你想锁定/解锁多个帐户，那么你需要找个脚本。</p><p>是的，我们可以编写一个小的 shell 脚本来执行这个操作。为此，请使用以下 shell 脚本。</p><p>创建用户列表。每个用户信息在单独的行中。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ cat user-lists.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>u1</span></span>
<span class="line"><span>u2</span></span>
<span class="line"><span>u3</span></span>
<span class="line"><span>u4</span></span>
<span class="line"><span>u5</span></span></code></pre></div><p>使用以下 shell 脚本锁定 Linux中 的多个用户帐户。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># user-lock.sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>for user in \`cat user-lists.txt\`</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>  passwd -l $user</span></span>
<span class="line"><span>done</span></span></code></pre></div><p>将 <code>user-lock.sh</code> 文件设置为可执行权限。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># chmod + user-lock.sh</span></span></code></pre></div><p>最后运行脚本来达成目标。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># sh user-lock.sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Locking password for user u1.</span></span>
<span class="line"><span>passwd: Success</span></span>
<span class="line"><span>Locking password for user u2.</span></span>
<span class="line"><span>passwd: Success</span></span>
<span class="line"><span>Locking password for user u3.</span></span>
<span class="line"><span>passwd: Success</span></span>
<span class="line"><span>Locking password for user u4.</span></span>
<span class="line"><span>passwd: Success</span></span>
<span class="line"><span>Locking password for user u5.</span></span>
<span class="line"><span>passwd: Success</span></span></code></pre></div><p>使用以下 shell 脚本检查锁定的用户帐户。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># vi user-lock-status.sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>for user in \`cat user-lists.txt\`</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>  passwd -S $user</span></span>
<span class="line"><span>done</span></span></code></pre></div><p>设置 <code>user-lock-status.sh</code> 可执行权限。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># chmod + user-lock-status.sh</span></span></code></pre></div><p>最后运行脚本来达成目标。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># sh user-lock-status.sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>u1 LK 2019-06-10 0 99999 7 -1 (Password locked.)</span></span>
<span class="line"><span>u2 LK 2019-06-10 0 99999 7 -1 (Password locked.)</span></span>
<span class="line"><span>u3 LK 2019-06-10 0 99999 7 -1 (Password locked.)</span></span>
<span class="line"><span>u4 LK 2019-06-10 0 99999 7 -1 (Password locked.)</span></span>
<span class="line"><span>u5 LK 2019-06-10 0 99999 7 -1 (Password locked.)</span></span></code></pre></div><p>使用下面的 shell 脚本来解锁多个用户。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># user-unlock.sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>for user in \`cat user-lists.txt\`</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>  passwd -u $user</span></span>
<span class="line"><span>done</span></span></code></pre></div><p>设置 <code>user-unlock.sh</code> 可执行权限。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># chmod + user-unlock.sh</span></span></code></pre></div><p>最后运行脚本来达成目标。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># sh user-unlock.sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Unlocking password for user u1.</span></span>
<span class="line"><span>passwd: Success</span></span>
<span class="line"><span>Unlocking password for user u2.</span></span>
<span class="line"><span>passwd: Success</span></span>
<span class="line"><span>Unlocking password for user u3.</span></span>
<span class="line"><span>passwd: Success</span></span>
<span class="line"><span>Unlocking password for user u4.</span></span>
<span class="line"><span>passwd: Success</span></span>
<span class="line"><span>Unlocking password for user u5.</span></span>
<span class="line"><span>passwd: Success</span></span></code></pre></div><p>运行相同的 shell 脚本 <code>user-lock-status.sh</code>，检查这些锁定的用户帐户在 Linux 中是否被解锁。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># sh user-lock-status.sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>u1 PS 2019-06-10 0 99999 7 -1 (Password set, SHA512 crypt.)</span></span>
<span class="line"><span>u2 PS 2019-06-10 0 99999 7 -1 (Password set, SHA512 crypt.)</span></span>
<span class="line"><span>u3 PS 2019-06-10 0 99999 7 -1 (Password set, SHA512 crypt.)</span></span>
<span class="line"><span>u4 PS 2019-06-10 0 99999 7 -1 (Password set, SHA512 crypt.)</span></span>
<span class="line"><span>u5 PS 2019-06-10 0 99999 7 -1 (Password set, SHA512 crypt.)</span></span></code></pre></div><hr>`,69)),l("p",null,[s[1]||(s[1]=a("via: ")),p(n,{href:"https://www.2daygeek.com/lock-unlock-disable-enable-user-account-linux/"},{default:e(()=>s[0]||(s[0]=[a("https://www.2daygeek.com/lock-unlock-disable-enable-user-account-linux/")])),_:1})]),l("p",null,[s[6]||(s[6]=a("作者：")),p(n,{href:"https://www.2daygeek.com/author/magesh/"},{default:e(()=>s[2]||(s[2]=[a("Magesh Maruthamuthu")])),_:1}),s[7]||(s[7]=a(" 选题：")),p(n,{href:"https://github.com/lujun9972"},{default:e(()=>s[3]||(s[3]=[a("lujun9972")])),_:1}),s[8]||(s[8]=a(" 译者：")),p(n,{href:"https://github.com/heguangzhi"},{default:e(()=>s[4]||(s[4]=[a("heguangzhi")])),_:1}),s[9]||(s[9]=a(" 校对：")),p(n,{href:"https://github.com/wxy"},{default:e(()=>s[5]||(s[5]=[a("wxy")])),_:1})]),l("p",null,[s[12]||(s[12]=a("本文由 ")),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>s[10]||(s[10]=[a("LCTT")])),_:1}),s[13]||(s[13]=a(" 原创编译，")),p(n,{href:"https://linux.cn/"},{default:e(()=>s[11]||(s[11]=[a("Linux中国")])),_:1}),s[14]||(s[14]=a(" 荣誉推出"))])])}const w=i(u,[["render",r]]);export{x as __pageData,w as default};
